package chromedp
import("context";"fmt";"testing";"github.com/chromedp/cdproto/cdp";"github.com/chromedp/cdproto/dom")
func baselineNode(id cdp.NodeID,children ...*Node)*Node{return &Node{Node:&cdp.Node{NodeID:id},Children:children}}
func baselineClosed(c <-chan struct{})bool{select{case <-c:return true;default:return false}}
func TestBaselineDOMRemoval(t *testing.T){root:=newNode(&cdp.Node{NodeID:1,Children:[]*cdp.Node{{NodeID:2,Children:[]*cdp.Node{{NodeID:3}}},{NodeID:4}}});removed:=root.Children[0];leaf:=removed.Children[0];sibling:=root.Children[1];root.Invalidated=make(chan struct{});f:=&Frame{Frame:&cdp.Frame{ID:"frame"},Root:root,Nodes:make(map[cdp.NodeID]*Node)};walk(f.Nodes,root);target:=&Target{frames:map[cdp.FrameID]*Frame{"frame":f},cur:"frame",logf:func(string,...any){},errf:func(string,...any){}};if f.Nodes[3]!=leaf||leaf.Parent!=removed{t.Fatal("normal DOM indexing failed")};target.domEvent(context.Background(),&dom.EventChildNodeRemoved{ParentNodeID:1,NodeID:2});if len(root.Children)!=1||root.Children[0]!=sibling||f.Nodes[2]!=nil{t.Fatal("direct child removal failed")};fmt.Printf("DOM removal normal: direct child gone; stale_descendant=%v removed_invalidated=%v sibling_invalidated=%v\n",f.Nodes[3]!=nil,baselineClosed(removed.Invalidated),baselineClosed(sibling.Invalidated))}
